dependencies <- function(instructions) {
  last_writer <- integer(32L)
  sources <- vector("list",length(instructions))
  for (i in seq_along(instructions)) {
    instruction <- instructions[[i]]
    current <- list()
    for (field in seq_len(2L)) {
      register <- c(instruction$rs1,instruction$rs2)[field]
      if (register > 0L) current[[length(current)+1L]] <- list(
          field=field,
          register=register,
          producer=last_writer[register+1L]
      )
    }
    sources[[i]] <- current
    if (instruction$rd > 0L) last_writer[instruction$rd+1L] <- i
  }
  sources
}
id_resolved <- function(
    instruction,
    variant
) (instruction$kind == "JUMP" && instruction$rs1 == -1L) || (instruction$kind %in% c(
    "BRANCH",
    "JUMP"
) && variant$stage == "ID")
ready_cycle <- function(instruction,producer,producer_time,variant) {
  if (!variant$forwarding) return(producer_time[5L]+1L)
  result <- if (producer$kind == "LOAD") producer_time[5L] else producer_time[4L]
  result+as.integer(id_resolved(instruction,variant))
}
forwarding_path <- function(instruction,producer_time,instruction_time,variant) {
  if (is.null(producer_time) || !variant$forwarding) return(1L)
  resolved <- id_resolved(instruction,variant)
  use_cycle <- instruction_time[3L]-as.integer(resolved)
  if (producer_time[4L] == use_cycle) return(2L)
  if (!resolved && producer_time[5L] == use_cycle) return(3L)
  1L
}

CAUSES <- c("control","structural","load_use","raw")
STAGES <- c("IF","ID","EX","MEM","WB")
simulate <- function(instructions,sources,variant,mispredicted) {
  n <- length(instructions)
  timings <- matrix(0L,n,5L)
  records <- list()
  delays <- integer()
  for (i in seq_along(instructions)) {
    instruction <- instructions[[i]]
    execute <- if (instruction$kind == "MUL") variant$latency else 1L
    if (i == 1L) {
      fetch <- 1L
      decode <- 2L
      start <- 3L
    } else {
      previous <- timings[i-1L,]
      fetch <- if (mispredicted[i-1L]) previous[3L]+as.integer(!id_resolved(
          instructions[[i-1L]],
          variant
      )) else previous[2L]
      decode <- max(fetch+1L,previous[3L])
      ideal <- previous[3L]+1L
      load_ready <- raw_ready <- ideal
      load_producer <- raw_producer <- 0L
      for (source in sources[[i]]) {
        p <- source$producer
        if (p == 0L) next
        ready <- ready_cycle(instruction,instructions[[p]],timings[p,],variant)
        if (instructions[[p]]$kind == "LOAD") {
          if (ready > load_ready) {
            load_ready <- ready
            load_producer <- p
          }
        } else if (ready > raw_ready) {
          raw_ready <- ready
          raw_producer <- p
        }
      }
      bounds <- c(decode+1L,previous[4L],load_ready,raw_ready)
      producers <- c(0L,0L,load_producer,raw_producer)
      start <- ideal
      for (cause in seq_len(4L)) if (bounds[cause] > start) {
        records[[length(records)+1L]] <- list(
            cause=cause,
            cycles=bounds[cause]-start,
            responsible=if (cause <= 2L) i-1L else i,
            waiting=i,
            producer=producers[cause]
        )
        start <- bounds[cause]
      }
      delays <- c(delays,start-ideal)
    }
    timings[i,] <- c(fetch,decode,start,start+execute,start+execute+1L)
  }
  if (instructions[[n]]$kind == "MUL" && variant$latency >= 2L) records[[length(records)+1L]] <- list(
      cause=2L,
      cycles=variant$latency-1L,
      responsible=n,
      waiting=0L,
      producer=0L
  )
  list(timings=timings,records=records,delays=delays,cycles=timings[n,5L])
}

btb <- function(entries) {
  table <- new.env(parent=emptyenv())
  table$tags <- rep(-1L,entries)
  table$targets <- integer(entries)
  table
}
lookup <- function(table,pc) {
  index <- (pc %/% 4L) %% length(table$tags)+1L
  if (table$tags[index] == pc) table$targets[index] else NULL
}
insert <- function(table,pc,target) {
  index <- (pc %/% 4L) %% length(table$tags)+1L
  table$tags[index] <- pc
  table$targets[index] <- target
}
ras <- function(depth) {
  result <- new.env(parent=emptyenv())
  result$depth <- depth
  result$stack <- integer()
  result
}
ras_push <- function(ras,address) {
  if (ras$depth == 0L) return(invisible(NULL))
  if (length(ras$stack) == ras$depth) ras$stack <- ras$stack[-1L]
  ras$stack <- c(ras$stack,address)
}
ras_pop <- function(ras) {
  if (!length(ras$stack)) return(NULL)
  value <- tail(ras$stack,1L)
  ras$stack <- head(ras$stack,-1L)
  value
}
updated <- function(counter,taken) if (taken) min(3L,counter+1L) else max(0L,counter-1L)
direction_predictor <- function(scheme,parameters) {
  result <- new.env(parent=emptyenv())
  result$scheme <- scheme
  result$parameters <- parameters
  result$history <- 0L
  if (scheme %in% c("ONEBIT","TWOBIT","GSHARE")) result$table <- rep(
      if (scheme == "ONEBIT") 0L else 1L,
      parameters[1L]
  )
  if (scheme == "TOURNAMENT") {
    result$local_table <- rep(1L,parameters[1L])
    result$global_table <- rep(1L,parameters[2L])
    result$chooser <- rep(1L,parameters[4L])
  }
  result
}
direction_prediction <- function(predictor,pc,target) {
  scheme <- predictor$scheme
  if (scheme %in% c("STATIC_NT","PERFECT")) return(FALSE)
  if (scheme == "BTFN") return(target < pc)
  if (scheme %in% c("ONEBIT","TWOBIT","GSHARE")) {
    key <- if (scheme == "GSHARE") bitwXor(pc %/% 4L,predictor$history) else pc %/% 4L
    index <- key %% length(predictor$table)+1L
    return(if (scheme == "ONEBIT") predictor$table[index] == 1L else predictor$table[index] >= 2L)
  }
  local <- predictor$local_table[(pc %/% 4L) %% length(predictor$local_table)+1L] >= 2L
  global <- predictor$global_table[bitwXor(
      pc %/% 4L,
      predictor$history
  ) %% length(predictor$global_table)+1L] >= 2L
  if (predictor$chooser[(pc %/% 4L) %% length(predictor$chooser)+1L] >= 2L) global else local
}
direction_update <- function(predictor,pc,taken) {
  scheme <- predictor$scheme
  if (scheme %in% c("STATIC_NT","BTFN","PERFECT")) return(invisible(NULL))
  if (scheme == "TOURNAMENT") {
    li <- (pc %/% 4L) %% length(predictor$local_table)+1L
    gi <- bitwXor(pc %/% 4L,predictor$history) %% length(predictor$global_table)+1L
    ci <- (pc %/% 4L) %% length(predictor$chooser)+1L
    lp <- predictor$local_table[li] >= 2L
    gp <- predictor$global_table[gi] >= 2L
    if (lp != gp) predictor$chooser[ci] <- updated(predictor$chooser[ci],gp == taken)
    predictor$local_table[li] <- updated(predictor$local_table[li],taken)
    predictor$global_table[gi] <- updated(predictor$global_table[gi],taken)
    predictor$history <- (2L*predictor$history+as.integer(taken)) %% bitwShiftL(1L,predictor$parameters[3L])
  } else {
    key <- if (scheme == "GSHARE") bitwXor(pc %/% 4L,predictor$history) else pc %/% 4L
    index <- key %% length(predictor$table)+1L
    predictor$table[index] <- if (scheme == "ONEBIT") as.integer(taken) else updated(
        predictor$table[index],
        taken
    )
    if (scheme == "GSHARE") predictor$history <- (2L*predictor$history+as.integer(taken)) %% bitwShiftL(
        1L,
        predictor$parameters[2L]
    )
  }
}
storage_bits <- function(predictor) {
  scheme <- predictor$scheme
  p <- predictor$parameters
  if (scheme %in% c("STATIC_NT","BTFN","PERFECT")) return(0L)
  if (scheme == "ONEBIT") return(p[1L])
  if (scheme == "TWOBIT") return(2L*p[1L])
  if (scheme == "GSHARE") return(2L*p[1L]+p[2L])
  2L*(p[1L]+p[2L]+p[4L])+p[3L]
}

decimal <- function(numerator,denominator) {
  scaled <- (2L*numerator*10000L+denominator) %/% (2L*denominator)
  paste0(scaled %/% 10000L,".",sprintf("%04d",scaled %% 10000L))
}
percentage <- function(numerator,denominator) {
  if (denominator == 0L) return("-")
  scaled <- (2L*numerator*10000L+denominator) %/% (2L*denominator)
  paste0(scaled %/% 100L,".",sprintf("%02d",scaled %% 100L))
}
reduced_fraction <- function(numerator,denominator) {
  a <- numerator
  b <- denominator
  while (b != 0L) {
    remainder <- a %% b
    a <- b
    b <- remainder
  }
  paste0(numerator %/% a,"/",denominator %/% a)
}
hexadecimal <- function(value) sprintf("%08x",as.integer(value))
register_text <- function(value) if (value == -1L) "-" else paste0("r",value)
cycle_heading <- function(start,ending) paste0(
    "cycle",
    strrep(" ",18L),
    paste(seq.int(start,ending) %% 10L,collapse="")
)
diagram_row <- function(number,pc,kind,characters,annotation="") {
  identifier <- if (number == 0L) "     -" else sprintf("%6d",number)
  paste0(identifier," ",hexadecimal(pc)," ",sprintf("%-6s",kind)," ",characters,annotation)
}
join_parts <- function(parts) {
  lines <- character()
  for (part in parts) {
    if (length(lines)) lines <- c(lines,"")
    lines <- c(lines,part)
  }
  lines
}
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}
